end
local hitT = setmetatable({}, { __mode = "k" })
local function killPass()
    local now = os.clock()
    for _, m in ipairs(liveEnemies(false)) do
        if not hitT[m] or now - hitT[m] > 0.3 then
            hitT[m] = now
            local v = m:FindFirstChild("HPValue")
            local hp = (v and tonumber(v.Value)) or tonumber(m:GetAttribute("MaxHP")) or 0
            local dmg = hp > 0 and hp * 2 or 1e30
            bind(RM.EnemyHit, m.Name, dmg, { Damage = dmg })
        end
    end
end
local function lootPass()
    for _, m in ipairs(liveEnemies(true)) do
        if on("sl_tp") then
            local r = m:FindFirstChild("HumanoidRootPart")
            if r then tp(r.Position + Vector3.new(0, 3, 0)); task.wait(0.1) end
        end
        for _ = 1, 25 do
            if not m.Parent or m:GetAttribute("Dead") == true then break end
            bind(RM.EnemyHit, m.Name, 1, {})
            task.wait(0.05)
        end
        if m:GetAttribute("Dead") == true then S.loots = S.loots + 1; notify("Super Loot defeated!") end
    end
end

