local function triggerPrompt(pp, walk)
    pcall(function() pp.HoldDuration = 0; pp.MaxActivationDistance = 1e6 end)
    if walk then
        local part = pp.Parent
        if part and part:IsA("BasePart") then tp(part.Position + Vector3.new(0, 3, 0)); task.wait(0.05) end
    end
