local function collectOres()
    local before = #orePrompts()
    for pass = 1, 3 do
        local list = orePrompts()
        if #list == 0 then break end
        for _, pp in ipairs(list) do triggerPrompt(pp, pass > 1) end
        task.wait(0.35)
    end
    local got = before - #orePrompts()
    if got > 0 then S.ores = S.ores + got end
    return got
end

local function farmCycle(n)
    if lp:GetAttribute("Dead") then S.state = "Dead · waiting"; task.wait(1); return end
    S.state = "Entering stage " .. n
    enterStage(n)
    if not waitFor(function() return #liveEnemies(false) > 0 end, 4) then
        S.state = "No enemies · stage " .. n
        exitFight(); task.wait(0.6); return
    end
    S.state = "Fighting stage " .. n
    waitFor(function() killPass(); return #liveEnemies(false) == 0 end, 20)
    if #liveEnemies(false) == 0 then S.clears = S.clears + 1 end
    if on("f_collect") then
        S.state = "Looting stage " .. n
        if waitFor(function() return #orePrompts() > 0 end, 4) then task.wait(0.25); collectOres() end
    end
    exitFight()
    task.wait(0.25)
end
