local function enhBoost(l) local c = lvlCfg(CFG.Enhant, tonumber(l) or 0); return c and tonumber(c.Boost) or 0 end
local function gearScores()
    local h = have()
    local best = { Weapon = 1, Armor = 0.1, Hat = 0.1 }
    for _, it in pairs(h) do
        local c = type(it) == "table" and itemCfg(it)
        if c and not c.BestPercent then
            local v = tonumber(it.Type == "Weapon" and c.Train or c.AttriNum) or 0
            if v > best[it.Type] then best[it.Type] = v end
        end
    end
    local out = {}
    for uuid, it in pairs(h) do
        local c = type(it) == "table" and itemCfg(it)
        if c then
            local base = tonumber(it.Type == "Weapon" and c.Train or c.AttriNum) or 0
            if c.BestPercent then
                local cap = tonumber(it.Type == "Weapon" and c.MaxTrain or c.MaxAttrNum) or math.huge
                base = math.min(best[it.Type] * base, cap)
            end
            out[uuid] = base * (1 + enhBoost(it.Level))
        end
    end
    return out
end
local function bestPerSlot(sc)
    local best = {}
    for uuid, it in pairs(have()) do
        local s = sc[uuid]
        if s and (not best[it.Type] or s > best[it.Type].s) then best[it.Type] = { u = uuid, s = s } end
    end
    return best
end
