local function oreRar(id) local c = CFG.Ore and CFG.Ore[id]; local r = c and c.Rarity; return type(r) == "number" and RARITY[r] or r end
local function orePower(id) local c = CFG.Ore and CFG.Ore[id]; return (c and tonumber(c.Power)) or tonumber(tostring(id):match("%d+")) or 0 end
local FORGE_MAKE = {
    ["Katana"] = { "Weapon", 4 }, ["Greatsword"] = { "Weapon", 13 },
    ["Light Hat"] = { "Armor", 4 }, ["Light Armor"] = { "Armor", 11 },
    ["Heavy Hat"] = { "Armor", 16 }, ["Heavy Armor"] = { "Armor", 23 },
}
local FORGE_ORDER = { "Katana", "Greatsword", "Light Hat", "Light Armor", "Heavy Hat", "Heavy Armor" }
local function forgeOnce()
    if not RM.Forge then return false, "Forge unavailable" end
    local make = FORGE_MAKE[Opt.fg_make.Value] or FORGE_MAKE.Katana
    local need = make[2]
    local rar, bestFirst, keep = multiSet("fg_rar"), on("fg_best"), math.floor(Opt.fg_keep.Value)
    local byId = {}
    for uuid, it in pairs(have()) do
        if type(it) == "table" and it.Type == "Ore" then
            local r = oreRar(it.ID)
            if not rar or (r and rar[r]) then
                local e = byId[it.ID] or { total = 0, stacks = {} }
                byId[it.ID] = e
                local n = tonumber(it.Number) or 1
                e.total = e.total + n
                e.stacks[#e.stacks + 1] = { u = uuid, n = n }
            end
        end
    end
    local ids = {}
    for id, e in pairs(byId) do ids[#ids + 1] = { e = e, p = orePower(id) } end
    table.sort(ids, function(a, b) if bestFirst then return a.p > b.p end return a.p < b.p end)
    local map, total, slots = {}, 0, 0
    for _, x in ipairs(ids) do
        if total >= need or slots >= 4 then break end
        local usable = x.e.total - keep
        for _, st in ipairs(x.e.stacks) do
            if usable <= 0 or total >= need or slots >= 4 then break end
            local take = math.min(st.n, usable, need - total)
            if take > 0 then map[st.u] = take; slots = slots + 1; total = total + take; usable = usable - take end
        end
    end
    if total < need then return false, "Need " .. need .. " ores (have " .. total .. ")" end
    local ok, res = invoke(RM.Forge, { ConfigType = make[1], UUIDList = map })
    if not ok or not res then return false, "Forge refused" end
    S.forges = S.forges + 1
    return true, "Forged " .. tostring(Opt.fg_make.Value)
end

local function enhanceStep()
    if eco("rebirth") < 6 then S.estate = "Needs rebirth 6"; return false end
    local slots = multiSet("e_slots")
    if not slots then S.estate = "Pick a slot"; return false end
    local eq, h, target = equiped(), have(), math.floor(Opt.e_target.Value)
    local waiting = nil
    for _, slot in ipairs(GEAR) do
        local uuid = slots[slot] and eq[slot]
        local it = uuid and h[uuid]
        if type(it) == "table" then
            local lvl = tonumber(it.Level) or 0
            local nx = lvlCfg(CFG.Enhant, lvl + 1)
            if lvl < target and nx then
                local opts, blocked = {}, nil
                if eco("coin") < (tonumber(nx.NeedCoin) or 0) then blocked = "coins"
                elseif material("EnhantStone_1") < (tonumber(nx.EnhantStone_1) or 0) or material("EnhantStone_2") < (tonumber(nx.EnhantStone_2) or 0) then blocked = "stones"
                elseif lvl >= 6 then
                    if on("e_protect") and material("EnhantProtect") > 0 then opts.UseProtect = true
                    elseif on("e_safe") then blocked = "scroll" end
                end
                if blocked then
                    waiting = waiting or (slot .. " +" .. lvl .. " · need " .. blocked)
                else
                    S.estate = string.format("%s +%d → +%d (%d%%)", slot, lvl, lvl + 1, math.floor((tonumber(nx.Percent) or 0) * 100 + 0.5))
                    invoke(RM.Enhant, uuid, opts)
                    waitFor(function() local i2 = have()[uuid]; return type(i2) == "table" and (tonumber(i2.Level) or 0) ~= lvl end, 2.5)
                    local i2 = have()[uuid]
                    local nl = type(i2) == "table" and (tonumber(i2.Level) or 0) or lvl
                    if nl > lvl then S.enhUp = S.enhUp + 1 elseif nl < lvl then S.enhDown = S.enhDown + 1 end
                    if nl >= target then notify(slot .. " reached +" .. nl) end
                    return true
                end
            end
        end
    end
    S.estate = waiting or "All at target"
    return false
end

local function classInfo(id)
    local c, s = CFG.Class and CFG.Class[id], CFG.ClassShow and CFG.ClassShow[id]
    return (s and s.DisplayName) or tostring(id or "None"), c and c.Rarity
end

local function bestTrainArea()
    local cfg = CFG.TrainArea; if type(cfg) ~= "table" then return nil end
    local reb, pem, best, bestN = eco("rebirth"), store("Pem"), 0, nil
    for i, c in ipairs(cfg) do
        local ok = reb >= (tonumber(c.NeedRebirth) or 0) and (not c.IsPay or pem["AutoTrainArea_" .. i])
        if ok and (tonumber(c.Basic) or 0) > best then best, bestN = tonumber(c.Basic) or 0, i end
    end
    return bestN
end
local trainQ = {}
local function refillTrain()
    local ok, buf = invoke(RM.TrainList)
    if not ok or buf == nil then return false end
    local list
    pcall(function()
        local raw = buf
        if typeof(buf) == "buffer" then
            raw = buffer.tostring(game:GetService("EncodingService"):DecompressBuffer(buf, Enum.CompressionAlgorithm.Zstd))
        end
        list = type(raw) == "table" and raw or HttpService:JSONDecode(raw)
    end)
    if type(list) ~= "table" then
        local eu = find("Utils.EncodingUtils")
        local okR, mod = pcall(require, eu)
        if okR and type(mod) == "table" then local _, r = gcall(mod.DecodeTable, buf); list = r end
    end
    if type(list) ~= "table" then return false end
    for _, v in ipairs(list) do trainQ[#trainQ + 1] = v end
    return true
end

local function claimAll()
    local which = multiSet("r_which") or {}
    if which.Online then
        local o = store("Online"); local rw = type(o.Reward) == "table" and o.Reward or {}
        for i = 1, 12 do
            if not rw[tostring(i)] and not rw[i] then fire(RM.Online, tostring(i)); task.wait(0.05) end
        end
    end
    if which.Offline and lp:GetAttribute("OfflineRewardValue") ~= nil then fire(RM.Offline) end
    if which.Index then
        local ix = store("Index"); local cl = type(ix.claimed) == "table" and ix.claimed or {}
        local n = 0
        if type(ix.unlocked) == "table" then
            for k in pairs(ix.unlocked) do
                if n >= 25 then break end
                local t, id = tostring(k):match("^([^-]+)-(.+)$")
                if t and not cl[k] then n = n + 1; invoke(RM.IndexExp, t, id) end
            end
        end
        local nx = lvlCfg(CFG.Index, (tonumber(ix.level) or 0) + 1)
        if nx and (tonumber(ix.exp) or 0) >= (tonumber(nx.NeedExp) or math.huge) then invoke(RM.IndexLvl) end
    end
    if which["Update Log"] and type(CFG.UpdateLog) == "table" then
        local pem = store("Pem")
        for i = 1, #CFG.UpdateLog do
            if not pem["UPDRD_" .. i] then fire(RM.UpdClaim, i); task.wait(0.1) end
        end
    end
    if which["Event Quests"] and type(CFG.Quest) == "table" then
        local ev = store("EnhantEvent")
        local rec, cl = type(ev.record) == "table" and ev.record or {}, type(ev.claimed) == "table" and ev.claimed or {}
        for id, q in pairs(CFG.Quest) do
            if not cl[id] and not cl[tostring(id)] and (tonumber(rec[q.NeedType]) or 0) >= (tonumber(q.NeedNumber) or math.huge) then
                fire(RM.Quest, tostring(id)); task.wait(0.1)
            end
        end
    end
    if which["Daily Ticket"] then
        local d, today = store("Dungeon"), Workspace:GetAttribute("today")
        if not (type(d.DailyGet) == "table" and today and d.DailyGet[today]) then fire(RM.DailyTicket) end
    end
end

