section("Settings", function()
    local lag = { on = false, saved = {} }
    local function strip(o)
        if o:IsA("ParticleEmitter") or o:IsA("Trail") or o:IsA("Beam") or o:IsA("Smoke") or o:IsA("Fire") or o:IsA("Sparkles") then pcall(function() o.Enabled = false end)
        elseif o:IsA("PointLight") or o:IsA("SpotLight") or o:IsA("SurfaceLight") then pcall(function() o.Enabled = false end)
        elseif o:IsA("Decal") or o:IsA("Texture") then pcall(function() o.Transparency = 1 end)
        elseif o:IsA("BasePart") then pcall(function() o.CastShadow = false end) end
    end
    local function setLag(state)
        if state and not lag.on then
            lag.on = true
            lag.saved.shadows = Lighting.GlobalShadows
            pcall(function() lag.saved.quality = settings().Rendering.QualityLevel end)
            pcall(function() Lighting.GlobalShadows = false end)
            for _, e in ipairs(Lighting:GetDescendants()) do
                if e:IsA("PostEffect") then lag.saved[e] = e.Enabled; pcall(function() e.Enabled = false end) end
            end
            pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
            for _, d in ipairs(Workspace:GetDescendants()) do strip(d) end
            lag.conn = track(Workspace.DescendantAdded:Connect(function(d) if lag.on then task.defer(strip, d) end end))
        elseif not state and lag.on then
            lag.on = false
            if lag.conn then pcall(function() lag.conn:Disconnect() end); lag.conn = nil end
            if lag.saved.shadows ~= nil then pcall(function() Lighting.GlobalShadows = lag.saved.shadows end) end
            if lag.saved.quality ~= nil then pcall(function() settings().Rendering.QualityLevel = lag.saved.quality end) end
            for k, v in pairs(lag.saved) do if typeof(k) == "Instance" then pcall(function() k.Enabled = v end) end end
            lag.saved = {}
        end
    end
    local Pf = Tabs.Settings:AddLeftGroupbox("Performance", "fast-forward")
    Pf:AddToggle("s_lag", { Text = "Lag Reducer", Default = false, Tooltip = "Fewer effects, more FPS" })
    Toggles.s_lag:OnChanged(function(v) setLag(v == true) end)
    onClean(function() setLag(false) end)
    Pf:AddLabel("Anti-AFK is always on.", true)

    local M = Tabs.Settings:AddRightGroupbox("Menu", "menu")
    M:AddButton({ Text = "Copy Debug Info", Func = function()
        local lines = { "LTF 2.0 debug", "PlaceId " .. game.PlaceId }
        local names = {}
        for k in pairs(DATA) do names[#names + 1] = tostring(k) end
        table.sort(names)
        lines[#lines + 1] = "stores: " .. table.concat(names, ",")
        lines[#lines + 1] = string.format("eco rebirth=%d level=%d coin=%d", eco("rebirth"), eco("level"), eco("coin"))
        lines[#lines + 1] = "attrs StageID=" .. tostring(lp:GetAttribute("StageID")) .. " IntoFight=" .. tostring(lp:GetAttribute("IntoFight")) .. " Dungeoning=" .. tostring(lp:GetAttribute("Dungeoning")) .. " TrainArea=" .. tostring(lp:GetAttribute("AutoTrainAreaID"))
        lines[#lines + 1] = "state=" .. S.state .. " | enh=" .. S.estate .. " | dun=" .. S.dstate .. " | race=" .. S.cstate
        lines[#lines + 1] = "trainQ=" .. #trainQ .. " trains=" .. S.trains .. " lastErr=" .. tostring(S.err)
        for k, v in pairs(_G.__CW_LTF_ERR or {}) do lines[#lines + 1] = "ERR " .. k .. ": " .. tostring(v):sub(1, 300) end
        pcall(setclipboard, table.concat(lines, "\n"))
        notify("Debug info copied.")
    end })
    M:AddButton({ Text = "Unload", Func = function()
        pcall(function() if _G.__CW_LTF_CLEAN then _G.__CW_LTF_CLEAN() end end)
        pcall(function() Library:Unload() end)
    end })
    M:AddLabel("Menu Toggle"):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = "Menu Toggle" })
    Library.ToggleKeybind = Opt.MenuKeybind
end)

