            lastRoll = nil
            stopRoll("Got " .. name .. " (" .. rar .. ")!")
        elseif type(c.lock) == "table" and c.lock[slot] then
            stopRoll("Race slot " .. slot .. " is locked")
        elseif (tonumber(c.luckTimes) or 0) <= 0 then
            stopRoll("Out of race rolls")
        else
            lastRoll = nil
            fire(RM.ClassRoll, slot)
            waitFor(function() return lastRoll ~= nil end, 5)
            task.wait(0.6)
        end
    end)
end

