        local c = store("Class")
        local name = classInfo(type(c.have) == "table" and c.have[tostring(c.equiped or "1")])
        UI.race:SetText(string.format("Rolls %d · %s", tonumber(c.luckTimes) or 0, name))
    end
    if UI.pot then
        local pot, parts = store("Potion"), {}
        for _, n in ipairs(POTIONS) do parts[#parts + 1] = n:gsub("Potion", "") .. " " .. (tonumber(pot[n]) or 0) end
        UI.pot:SetText(table.concat(parts, " · "))
    end
end)

